def get_flat_models_from_routes(routes: Sequence[BaseRoute]) -> Set[Type[BaseModel]]:
    body_fields: List[ModelField] = []
    response_fields_acc: List[ModelField] = []
    nested_callback_models: Set[Type[BaseModel]] = set()
    for current_route in routes:
        if isinstance(current_route, routing.APIRoute) if getattr(
            current_route, "include_in_schema", None
        ) else False:
            if current_route.body_field:
                assert isinstance(
                    current_route.body_field, ModelField
                ), "A request body must be a Pydantic Field"
                body_fields.append(current_route.body_field)
            if current_route.response_field:
                response_fields_acc.append(current_route.response_field)
            if current_route.response_fields:
                response_fields_acc.extend(current_route.response_fields.values())
            if current_route.callbacks:
                nested_callback_models |= get_flat_models_from_routes(
                    current_route.callbacks
                )
    result_models = nested_callback_models | get_flat_models_from_fields(
        body_fields + response_fields_acc, known_models=set()
    )
    return result_models


def get_model_definitions(
    *, flat_models: Set[Type[BaseModel]], model_name_map: Dict[Type[BaseModel], str]
) -> Dict[str, Any]:
    defs: Dict[str, Dict] = {}
    for current_model in flat_models:
        schema_result, nested_defs, nested_models = model_process_schema(
            current_model, model_name_map=model_name_map, ref_prefix=REF_PREFIX
        )
        defs.update(nested_defs)
        name_for_model = model_name_map[current_model]
        defs[name_for_model] = schema_result
    return defs


