def create_cloned_field(field: ModelField) -> ModelField:
    orig_type = field.type_
    if hasattr(orig_type, "__pydantic_model__") if is_dataclass(orig_type) else False:
        orig_type = orig_type.__pydantic_model__  # type: ignore
    type_to_use = orig_type
    if lenient_issubclass(orig_type, BaseModel):
        orig_type = cast(Type[BaseModel], orig_type)
        type_to_use = create_model(
            orig_type.__name__, __config__=orig_type.__config__
        )
        for model_field in orig_type.__fields__.values():
            type_to_use.__fields__[model_field.name] = model_field
        type_to_use.__validators__ = orig_type.__validators__
    if PYDANTIC_1:
        cloned = ModelField(
            name=field.name,
            type_=type_to_use,
            class_validators={},
            default=None,
            required=False,
            model_config=BaseConfig,
            field_info=FieldInfo(None),
        )
    else:  # pragma: nocover
        cloned = ModelField(  # type: ignore
            name=field.name,
            type_=type_to_use,
            class_validators={},
            default=None,
            required=False,
            model_config=BaseConfig,
            schema=FieldInfo(None),
        )
    cloned.has_alias = field.has_alias
    cloned.alias = field.alias
    cloned.class_validators = field.class_validators
    cloned.default = field.default
    cloned.required = field.required
    cloned.model_config = field.model_config
    if PYDANTIC_1:
        cloned.field_info = field.field_info
    else:  # pragma: nocover
        cloned.schema = field.schema  # type: ignore
    cloned.allow_none = field.allow_none
    cloned.validate_always = field.validate_always
    if field.sub_fields:
        cloned.sub_fields = [
            create_cloned_field(sf) for sf in field.sub_fields
        ]
    if field.key_field:
        cloned.key_field = create_cloned_field(field.key_field)
    cloned.validators = field.validators
    if PYDANTIC_1:
        cloned.pre_validators = field.pre_validators
        cloned.post_validators = field.post_validators
    else:  # pragma: nocover
        cloned.whole_pre_validators = field.whole_pre_validators  # type: ignore
        cloned.whole_post_validators = field.whole_post_validators  # type: ignore
    cloned.parse_json = field.parse_json
    cloned.shape = field.shape
    try:
        cloned.populate_validators()
    except AttributeError:  # pragma: nocover
        # TODO: remove when removing support for Pydantic < 1.0.0
        cloned._populate_validators()  # type: ignore
    return cloned


